begin;
create function public.test_assert(ok boolean, message text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'ASSERT: %',message; end if; end $$;
insert into auth.users values ('10000000-0000-4000-8000-000000000001');
insert into public.workspaces values ('20000000-0000-4000-8000-000000000001','personal');
insert into public.workspace_members values ('20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','active','owner');
insert into public.profiles values ('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001');
insert into public.accounts values ('40000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001');
insert into public.subscriptions(id,workspace_id,plan_id,status,asaas_subscription_id,updated_at) values ('30000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','pro','active','sub_fixture','2026-10-01Z');
set local role service_role;
select public.test_assert(public.apply_billing_lifecycle('30000000-0000-4000-8000-000000000001','2026-10-01Z','{"status":"suspended","billing_grace_ends_at":"2026-10-04T03:00:00Z"}', '[{"key":"pay_fixture:suspended","stage":"suspended"}]','[{"workspace_id":"20000000-0000-4000-8000-000000000001","asaas_payment_id":"pay_fixture","asaas_subscription_id":"sub_fixture","status":"overdue","billing_type":"pix","value":29.9,"due_date":"2026-10-01"}]','2026-10-05Z'),'atomic apply');
select public.test_assert(not public.apply_billing_lifecycle('30000000-0000-4000-8000-000000000001','2026-10-01Z','{"status":"active"}','[]','[]','2026-10-05Z'),'stale writer denied');
select public.test_assert(public.apply_billing_lifecycle('30000000-0000-4000-8000-000000000001',(select updated_at from public.subscriptions limit 1),'{}','[{"key":"pay_fixture:suspended","stage":"suspended"}]','[]','2026-10-05Z'),'repeat notice');
reset role;
select public.test_assert((select count(*)=1 from public.notifications),'notice deduplicated');
select public.test_assert((select count(*)=1 from public.billing_notice_deliveries),'delivery receipt unique');
select public.test_assert((select count(*)=1 from public.billing_payments),'real payment mirror');
select public.test_assert(not has_function_privilege('anon','public.apply_billing_lifecycle(uuid,timestamptz,jsonb,jsonb,jsonb,timestamptz)','execute'),'anon RPC denied');
select public.test_assert(not has_function_privilege('authenticated','public.apply_billing_lifecycle(uuid,timestamptz,jsonb,jsonb,jsonb,timestamptz)','execute'),'user RPC denied');
select public.test_assert(not has_function_privilege('authenticated','public.execute_confirmed_financial_action(uuid,text,uuid,text,text,text,uuid,text,text,numeric,date,uuid,numeric)','execute'),'legacy RPC overload denied');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',true);
set local role authenticated;
select public.test_assert((select count(*)=0 from public.accounts),'suspension read denied by RLS');
do $$ begin
 begin insert into public.accounts values(gen_random_uuid(),'20000000-0000-4000-8000-000000000001'); raise exception 'write bypass'; exception when insufficient_privilege then null; end;
 begin perform public.get_derived_account_balances(); raise exception 'balance RPC bypass'; exception when insufficient_privilege then null; end;
 begin perform public.get_derived_workspace_balance(); raise exception 'workspace balance RPC bypass'; exception when insufficient_privilege then null; end;
 begin perform public.execute_confirmed_financial_action(null,null,null,null,null,null,null,null,null,null,null,null,null,null); raise exception 'financial RPC bypass'; exception when insufficient_privilege then null; end;
end $$;
reset role;
select public.test_assert((select count(*)=1 from public.accounts),'financial data preserved');
set local role service_role;
select public.test_assert(public.apply_billing_lifecycle('30000000-0000-4000-8000-000000000001',(select updated_at from public.subscriptions limit 1),'{"status":"active","current_period_ends_at":"2099-11-01Z"}','[{"key":"reactivated:2099-11-01","stage":"reactivated"}]','[]','2026-10-05Z'),'automatic reactivation');
reset role;
set local role authenticated;
select public.test_assert((select count(*)=1 from public.accounts),'access restored');
rollback;
